SELECT
  ROUND(COALESCE(SUM(so.total_amount) FILTER (
    WHERE so.order_date >= DATE '2025-02-01' AND so.order_date < DATE '2025-03-01'
  ), 0), 2) AS february_2025_sales_order_value,
  ROUND(COALESCE(SUM(so.total_amount) FILTER (
    WHERE so.order_date >= DATE '2024-02-01' AND so.order_date < DATE '2024-03-01'
  ), 0), 2) AS february_2024_sales_order_value,
  ROUND(
    100.0 * (
      COALESCE(SUM(so.total_amount) FILTER (
        WHERE so.order_date >= DATE '2025-02-01' AND so.order_date < DATE '2025-03-01'
      ), 0)
      - COALESCE(SUM(so.total_amount) FILTER (
        WHERE so.order_date >= DATE '2024-02-01' AND so.order_date < DATE '2024-03-01'
      ), 0)
    ) / NULLIF(COALESCE(SUM(so.total_amount) FILTER (
      WHERE so.order_date >= DATE '2024-02-01' AND so.order_date < DATE '2024-03-01'
    ), 0), 0),
    2
  ) AS percent_change
FROM sales_orders so
WHERE so.status NOT IN ('DRAFT', 'CANCELLED', 'CREDIT_BLOCKED')
  AND (
    (so.order_date >= DATE '2025-02-01' AND so.order_date < DATE '2025-03-01')
    OR (so.order_date >= DATE '2024-02-01' AND so.order_date < DATE '2024-03-01')
  )
